-- # Lernfeld 5: Cyberphysische Systeme > ## Datengrundlagen > - Datenmengen

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann eine kleine Datenmenge allein durch ihre Größe als Big Data klassifiziert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Big Data erfordert Volumen, Vielfalt und Geschwindigkeit"}, {"text": "Ja", "correct": false, "because": "Größe allein reicht nicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind große Datenmengen zwangsläufig mit einer hohen Verarbeitungskomplexität verbunden?', 2, '[{"text": "Nein", "correct": true, "because": "Komplexität hängt von Struktur und Analyse ab"}, {"text": "Ja", "correct": false, "because": "Einfache Daten können groß sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist es möglich, dass eine Datenmenge durch Reduktion ihre analytische Aussagekraft steigert?', 2, '[{"text": "Ja", "correct": true, "because": "Relevanz kann durch Fokus steigen"}, {"text": "Nein", "correct": false, "because": "Reduktion kann nützlich sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Können heterogene Datenmengen ohne Vereinheitlichung effizient verarbeitet werden?', 2, '[{"text": "Nein", "correct": true, "because": "Heterogenität erschwert Analyse"}, {"text": "Ja", "correct": false, "because": "Vereinheitlichung oft nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind kleine Datenmengen immer schneller zu verarbeiten als große Datenmengen?', 2, '[{"text": "Nein", "correct": true, "because": "Komplexität kann Zeit übersteigen"}, {"text": "Ja", "correct": false, "because": "Größe allein entscheidet nicht"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Einheit beschreibt eine Datenmenge von 10^18 Bytes am präzisesten?', 2, '[{"text": "Exabyte", "correct": true, "because": "1 EB = 10^18 Bytes"}, {"text": "Petabyte", "correct": false, "because": "1 PB = 10^15 Bytes"}, {"text": "Zettabyte", "correct": false, "because": "1 ZB = 10^21 Bytes"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erhöht die Verarbeitungsanforderungen einer Datenmenge am stärksten?', 3, '[{"text": "Heterogenität der Daten", "correct": true, "because": "Unterschiedliche Formate erschweren Analyse"}, {"text": "Speicherort", "correct": false, "because": "Weniger Einfluss"}, {"text": "Komprimierungsgrad", "correct": false, "because": "Eher technisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist die primäre Herausforderung bei der Verwaltung extrem großer Datenmengen?', 2, '[{"text": "Skalierbarkeit der Infrastruktur", "correct": true, "because": "Systeme müssen mitwachsen"}, {"text": "Datenkomprimierung", "correct": false, "because": "Sekundär"}, {"text": "Eingabezeit", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datenmenge wird typischerweise als Grenze für Big Data betrachtet?', 2, '[{"text": "Terabyte-Bereich und darüber", "correct": true, "because": "Ab TB wird Volumen relevant"}, {"text": "Gigabyte-Bereich", "correct": false, "because": "Zu klein für Big Data"}, {"text": "Kilobyte-Bereich", "correct": false, "because": "Viel zu klein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaft macht eine Datenmenge besonders schwer vorhersehbar?', 2, '[{"text": "Hohe Varianz", "correct": true, "because": "Unregelmäßigkeiten erschweren Prognosen"}, {"text": "Kleine Größe", "correct": false, "because": "Weniger Einfluss"}, {"text": "Statische Struktur", "correct": false, "because": "Vorhersagbarer"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale charakterisieren Big Data zusätzlich zur reinen Datenmenge?', 4, '[{"text": "Variety (Vielfalt)", "correct": true, "because": "Unterschiedliche Typen"}, {"text": "Velocity (Geschwindigkeit)", "correct": true, "because": "Datenflussrate"}, {"text": "Volume (Volumen)", "correct": true, "because": "Größe ist Kern"}, {"text": "Visibility (Sichtbarkeit)", "correct": false, "because": "Kein Big-Data-Merkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der Verarbeitung großer Datenmengen auftreten?', 3, '[{"text": "Speicherengpässe", "correct": true, "because": "Platz wird knapp"}, {"text": "Hohe Latenz", "correct": true, "because": "Verarbeitung dauert"}, {"text": "Datenverlust", "correct": true, "because": "Fehler möglich"}, {"text": "Geringe Komplexität", "correct": false, "because": "Widerspricht Größe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken helfen, große Datenmengen effizient zu handhaben?', 3, '[{"text": "Parallele Verarbeitung", "correct": true, "because": "Aufteilung beschleunigt"}, {"text": "Datenkomprimierung", "correct": true, "because": "Reduziert Speicherbedarf"}, {"text": "Manuelle Analyse", "correct": false, "because": "Zu langsam"}, {"text": "Verteilte Systeme", "correct": true, "because": "Skalierbarkeit erhöht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen kleine Datenmengen für bestimmte Analysen vorteilhaft?', 4, '[{"text": "Schnelle Verarbeitung", "correct": true, "because": "Weniger Ressourcen nötig"}, {"text": "Geringere Komplexität", "correct": true, "because": "Einfacher zu handhaben"}, {"text": "Hohe Varianz", "correct": false, "because": "Unabhängig von Größe"}, {"text": "Leichte Interpretierbarkeit", "correct": true, "because": "Übersichtlicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Verwaltung heterogener Datenmengen?', 3, '[{"text": "Datenformate", "correct": true, "because": "Unterschiede erschweren"}, {"text": "Datenquellen", "correct": true, "because": "Vielfalt erhöht Komplexität"}, {"text": "Speicherkapazität", "correct": true, "because": "Muss angepasst sein"}, {"text": "Erfassungszeit", "correct": false, "because": "Weniger relevant"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Große Datenmengen sind immer unstrukturiert. b) Kleine Datenmengen sind für Echtzeitanwendungen ungeeignet.', 3, '[{"text": "Beides falsch", "correct": true, "because": "Größe definiert nicht Struktur, kleine Daten für Echtzeit nutzbar"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beides falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Verarbeitungsgeschwindigkeit skaliert linear mit der Datenmenge. b) Big Data erfordert verteilte Systeme.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Skalierung nicht linear, Big Data braucht Verteilung"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Heterogene Datenmengen sind einfacher zu komprimieren als homogene. b) Kleine Datenmengen schließen komplexe Analysen aus.', 3, '[{"text": "Beides falsch", "correct": true, "because": "Heterogen schwerer, kleine Daten analysierbar"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beides falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Eine Datenmenge von 1 PB gilt als Big Data unabhängig vom Kontext. b) Die Aussagekraft großer Datenmengen ist immer höher als die kleiner.', 3, '[{"text": "Beides falsch", "correct": true, "because": "Kontext entscheidend, Aussagekraft nicht garantiert"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beides falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Speicheranforderungen großer Datenmengen können durch Sampling eliminiert werden. b) Homogene Datenmengen sind einfacher zu skalieren.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Sampling reduziert, aber nicht eliminiert; Homogenität hilft"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]');

